// Validation: length, website, hashtag cap, banned language, emoji, in batch duplicates,
// and similarity against every post already published in the campaign.
const cfg = $('Config').first().json;
const plan = $('Determine Current Campaign Day').first().json;
const site = cfg.website || 'https://www.stratai.live';
const maxChars = Number(cfg.maxChars || 240);
const raw = $input.first().json || {};

let payload = raw;
if (raw.message && raw.message.content !== undefined) { payload = raw.message.content; }
else if (raw.content !== undefined) { payload = raw.content; }
else if (raw.choices && raw.choices[0] && raw.choices[0].message) { payload = raw.choices[0].message.content; }
else if (raw.text !== undefined) { payload = raw.text; }

if (typeof payload === 'string') {
  const s = payload.trim();
  const a = s.indexOf('{');
  const b = s.lastIndexOf('}');
  try { payload = JSON.parse(a >= 0 && b > a ? s.slice(a, b + 1) : s); } catch (e) { payload = null; }
}

let list = [];
if (payload && Array.isArray(payload.posts)) { list = payload.posts; }
else if (Array.isArray(payload)) { list = payload; }

const issues = [];
if (list.length !== 5) { issues.push('Expected 5 posts, received ' + list.length); }

const BANNED = ['guaranteed', 'guarantee', 'sure shot', 'sureshot', 'jackpot', 'multibagger', 'risk free', 'risk-free', 'no risk', 'assured return', 'double your money', 'get rich', 'free money', 'signal provider', 'buy now', 'sell now', 'tip of the day', 'intraday tips', 'dm for calls', 'join now', 'hurry', 'limited time', 'last chance', 'act fast', 'dont miss', 'do not miss', '100% accurate', 'profit daily', 'daily profit', 'confirm profit'];

function tokens(s) {
  const out = [];
  const low = String(s).toLowerCase();
  for (const ch of low) {
    out.push((ch >= 'a' && ch <= 'z') || (ch >= '0' && ch <= '9') ? ch : ' ');
  }
  return out.join('').split(' ').filter(w => w.length > 3);
}

function jaccard(a, b) {
  const A = new Set(a);
  const B = new Set(b);
  if (!A.size || !B.size) { return 0; }
  let inter = 0;
  A.forEach(w => { if (B.has(w)) { inter += 1; } });
  return inter / (A.size + B.size - inter);
}

const historyRows = $('Load Campaign Database').all().map(i => i.json).filter(r => r && r['Post Text']);
const historyTokens = historyRows.slice(-300).map(r => tokens(r['Post Text']));

const cleaned = [];
const batchTokens = [];

list.forEach((p, idx) => {
  const n = idx + 1;
  let text = String((p && (p.text || p.post || p.content)) || '').split('\r').join('').trim();
  if (text.length > 1 && text.charAt(0) === '"' && text.charAt(text.length - 1) === '"') {
    text = text.slice(1, -1).trim();
  }
  // Auto repair: append the site if the model dropped it and there is room.
  if (!text.includes(site)) {
    const candidate = text + '\n' + site;
    if (candidate.length <= maxChars) { text = candidate; }
  }
  text = text.trim();

  const chars = text.length;
  if (chars > maxChars) { issues.push('Post ' + n + ' is ' + chars + ' characters, limit is ' + maxChars); }
  if (chars < 60) { issues.push('Post ' + n + ' is too short at ' + chars + ' characters'); }
  if (!text.includes(site)) { issues.push('Post ' + n + ' does not contain ' + site); }

  const hashtags = text.split('#').length - 1;
  if (hashtags > 2) { issues.push('Post ' + n + ' uses ' + hashtags + ' hashtags, limit is 2'); }

  const low = text.toLowerCase();
  BANNED.forEach(w => { if (low.includes(w)) { issues.push('Post ' + n + ' contains banned wording: ' + w); } });

  if (Array.from(text).some(ch => ch.codePointAt(0) > 8500)) { issues.push('Post ' + n + ' contains an emoji or symbol character'); }

  const tok = tokens(text);
  batchTokens.forEach((prev, j) => {
    if (jaccard(tok, prev) >= 0.55) { issues.push('Post ' + n + ' duplicates post ' + (j + 1) + ' in this batch'); }
  });
  if (historyTokens.some(prev => jaccard(tok, prev) >= 0.5)) {
    issues.push('Post ' + n + ' is too similar to a post already published in the campaign');
  }
  batchTokens.push(tok);

  const slot = (plan.schedule || [])[idx] || {};
  cleaned.push({
    postNumber: n,
    contentType: (p && (p.content_type || p.contentType)) || (plan.contentTypes || [])[idx] || '',
    hook: (p && (p.hook_used || p.hook)) || (plan.hooks || [])[idx] || '',
    angle: (p && p.angle) || '',
    text,
    chars: text.length,
    hashtags,
    scheduledIso: slot.iso || null,
    scheduledDisplay: slot.display || '',
    baseSlot: slot.baseSlot || ''
  });
});

const uniqueIssues = Array.from(new Set(issues));

let totalTokens = null;
if (raw.usage && raw.usage.total_tokens) { totalTokens = raw.usage.total_tokens; }
else if (raw.tokenUsage && raw.tokenUsage.totalTokens) { totalTokens = raw.tokenUsage.totalTokens; }
else { totalTokens = Math.round((JSON.stringify(payload || {}) || '').length / 4); }

const repairPrompt = [
  'Your previous output for Campaign Day ' + plan.campaignDay + ' failed validation.',
  '',
  'ISSUES FOUND:',
  uniqueIssues.length ? uniqueIssues.map(x => '- ' + x).join('\n') : '- unknown formatting error',
  '',
  'Regenerate all five posts from scratch. Fix every issue. Keep every hard rule, especially the ' + maxChars + ' character ceiling including the URL, the two hashtag maximum, no emojis, and the closing URL ' + site + '.',
  '',
  'ORIGINAL BRIEF:',
  plan.userPrompt,
  '',
  'Return only the JSON object.'
].join('\n');

return [{
  json: {
    validationPassed: uniqueIssues.length === 0 && cleaned.length === 5,
    issues: uniqueIssues,
    issueCount: uniqueIssues.length,
    campaignDay: plan.campaignDay,
    theme: plan.theme,
    model: plan.model,
    totalTokens,
    generatedAt: $now.setZone(plan.timezone || 'Asia/Kolkata').toISO(),
    posts: cleaned,
    repairPrompt
  }
}];

