// Expands the validated batch into one sheet row per post, with its randomised slot time.
const cfg = $('Config').first().json;
const v = $input.first().json;
const zone = cfg.timezone || 'Asia/Kolkata';
const createdAt = $now.setZone(zone).toISO();

return (v.posts || []).map(p => ({
  json: {
    'Campaign Day': v.campaignDay,
    'Theme': v.theme,
    'Post #': p.postNumber,
    'Post Text': p.text,
    'Scheduled Time': p.scheduledIso,
    'Status': 'SCHEDULED',
    'Tweet ID': '',
    'Created': createdAt,
    'Posted': ''
  }
}));

// Builds the morning HTML briefing: theme, all five posts, posting time, character count.
const cfg = $('Config').first().json;
const zone = cfg.timezone || 'Asia/Kolkata';
const rows = $input.all().map(i => i.json).filter(r => r && r['Post Text']);
const day = rows.length ? rows[0]['Campaign Day'] : '';
const theme = rows.length ? rows[0]['Theme'] : '';
const stamp = $now.setZone(zone).toFormat('dd LLL yyyy');

function esc(s) {
  return String(s === null || s === undefined ? '' : s)
    .split('&').join('&amp;')
    .split('<').join('&lt;')
    .split('>').join('&gt;');
}

const cards = rows.map(r => {
  const text = String(r['Post Text']);
  const dt = DateTime.fromISO(String(r['Scheduled Time']), { zone });
  const when = dt.isValid ? dt.toFormat('HH:mm') + ' IST' : String(r['Scheduled Time']);
  return [
    `<div style='border:1px solid #232830;border-radius:12px;padding:16px;margin-bottom:14px;background:#0e1116;'>`,
    `<div style='font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:#7c8797;margin-bottom:10px;'>Post ${esc(r['Post #'])} &middot; ${esc(when)} &middot; ${text.length} characters</div>`,
    `<div style='font-size:14px;line-height:1.65;color:#e6e8eb;white-space:pre-wrap;'>${esc(text)}</div>`,
    `</div>`
  ].join('');
}).join('');

const html = [
  `<div style='font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;background:#0b0d10;padding:32px;color:#e6e8eb;'>`,
  `<div style='max-width:660px;margin:0 auto;background:#12151a;border:1px solid #232830;border-radius:16px;padding:28px;'>`,
  `<div style='font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:#7c8797;'>Strat AI &middot; X Campaign</div>`,
  `<h1 style='margin:10px 0 4px;font-size:24px;color:#ffffff;font-weight:600;letter-spacing:-0.01em;'>Day ${esc(day)} of 60</h1>`,
  `<div style='font-size:14px;color:#9fb0c3;margin-bottom:24px;'>Theme: <span style='color:#4ade80;'>${esc(theme)}</span> &middot; ${esc(stamp)}</div>`,
  cards,
  `<div style='font-size:12px;color:#5f6a78;border-top:1px solid #232830;padding-top:16px;margin-top:8px;'>${rows.length} posts queued. The publisher checks every five minutes and posts each one at its scheduled time. Tweet IDs are written back to the sheet.</div>`,
  `</div></div>`
].join('');

return [{
  json: {
    subject: 'Today\'s Strat AI Campaign — Day ' + day + ': ' + theme,
    html,
    campaignDay: day,
    theme,
    postCount: rows.length,
    totalChars: rows.reduce((a, r) => a + String(r['Post Text']).length, 0)
  }
}];

// Selects rows whose scheduled time has arrived and that have not been published yet.
const cfg = $('Dispatch Config').first().json;
const zone = cfg.timezone || 'Asia/Kolkata';
const nowMs = $now.setZone(zone).toMillis();
const maxPerCycle = Number(cfg.maxPerCycle || 5);
const maxLateMs = Number(cfg.maxLateMinutes || 240) * 60 * 1000;

const due = [];
const items = $input.all();

items.forEach((item, idx) => {
  const r = item.json || {};
  if (!r['Post Text']) { return; }
  const status = String(r['Status'] || '').toUpperCase();
  if (status !== 'SCHEDULED' && status !== 'RETRY') { return; }
  const when = DateTime.fromISO(String(r['Scheduled Time']), { zone });
  if (!when.isValid) { return; }
  const ms = when.toMillis();
  if (ms > nowMs) { return; }
  if (nowMs - ms > maxLateMs) { return; }
  due.push({
    json: {
      row_number: r.row_number || (idx + 2),
      'Campaign Day': r['Campaign Day'],
      'Theme': r['Theme'],
      'Post #': r['Post #'],
      'Post Text': String(r['Post Text']),
      'Scheduled Time': r['Scheduled Time'],
      'Status': status,
      chars: String(r['Post Text']).length,
      lateMinutes: Math.round((nowMs - ms) / 60000)
    }
  });
});

due.sort((a, b) => String(a.json['Scheduled Time']).localeCompare(String(b.json['Scheduled Time'])));

return due.slice(0, maxPerCycle);

// Turns the error trigger payload into an HTML incident mail.
const e = $input.first().json || {};
const wf = e.workflow || {};
const ex = e.execution || {};
const err = ex.error || e.error || {};
const stamp = $now.setZone('Asia/Kolkata').toFormat('dd LLL yyyy HH:mm') + ' IST';

function esc(s) {
  return String(s === null || s === undefined ? '' : s)
    .split('&').join('&amp;')
    .split('<').join('&lt;')
    .split('>').join('&gt;');
}

const node = err.node && err.node.name ? err.node.name : (ex.lastNodeExecuted || 'unknown node');
const message = err.message || 'No error message supplied';
const stack = err.stack || err.description || '';

const html = [
  `<div style='font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;background:#0b0d10;padding:28px;color:#e6e8eb;'>`,
  `<div style='max-width:660px;margin:0 auto;background:#12151a;border:1px solid #3a2226;border-radius:16px;padding:26px;'>`,
  `<div style='font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:#f87171;'>Automation Incident</div>`,
  `<h1 style='margin:10px 0 6px;font-size:21px;color:#ffffff;font-weight:600;'>${esc(wf.name || 'Strat AI X Marketing Automation')}</h1>`,
  `<div style='font-size:13px;color:#9fb0c3;margin-bottom:20px;'>${esc(stamp)} &middot; execution ${esc(ex.id || 'n/a')} &middot; mode ${esc(ex.mode || 'n/a')}</div>`,
  `<table style='width:100%;border-collapse:collapse;font-size:13px;'>`,
  `<tr><td style='padding:8px 0;color:#7c8797;width:130px;'>Failed node</td><td style='padding:8px 0;color:#e6e8eb;'>${esc(node)}</td></tr>`,
  `<tr><td style='padding:8px 0;color:#7c8797;'>Retries</td><td style='padding:8px 0;color:#e6e8eb;'>exhausted</td></tr>`,
  `<tr><td style='padding:8px 0;color:#7c8797;'>Execution URL</td><td style='padding:8px 0;color:#7dd3fc;'>${esc(ex.url || 'n/a')}</td></tr>`,
  `</table>`,
  `<p style='font-size:12px;color:#7c8797;margin-top:18px;'>Message</p>`,
  `<pre style='background:#0e1116;border:1px solid #232830;border-radius:10px;padding:14px;font-size:12px;color:#f0a5a5;white-space:pre-wrap;'>${esc(message)}</pre>`,
  stack ? `<p style='font-size:12px;color:#7c8797;margin-top:14px;'>Detail</p><pre style='background:#0e1116;border:1px solid #232830;border-radius:10px;padding:14px;font-size:11px;color:#9fb0c3;white-space:pre-wrap;'>${esc(String(stack).slice(0, 2000))}</pre>` : '',
  `</div></div>`
].join('');

return [{
  json: {
    subject: 'Strat AI automation failure — ' + node,
    html,
    node,
    message,
    executionId: ex.id || null
  }
}];
